def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if len(set(grid[r])) == 1}
    cols = {c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
